"""Build the authored Japanese canonical campaign. Run explicitly; no import side effects."""
from pathlib import Path
import re, json, shutil
from PIL import Image, ImageOps
R=Path(__file__).resolve().parents[1]
LOC={}
def loc(k,ru,en): LOC[k]=(ru,en)
def write(p,s,bom=False):
 p=R/p; p.parent.mkdir(parents=True,exist_ok=True)
 s='\n'.join(line.rstrip() for line in s.splitlines())+'\n'
 p.write_text(s,encoding='utf-8-sig' if bom else 'utf-8',newline='\n')
def read(p):return (R/p).read_text(encoding='utf-8-sig')
def change(p,a,b):
 s=read(p)
 if a in s: write(p,s.replace(a,b))
 elif b not in s: raise AssertionError((p,a))

def main():
 if (R/'common/national_focus/a03_focus.txt').exists() and '# JPS layout normalized' in read('common/national_focus/a03_focus.txt'):
  raise SystemExit('Extended story detected. Use extend_japan_story.py; baseline rebuild would erase authored postwar content.')
